// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: ownerCandidate is the initial owner (fuzz will pick an address),
    // newOwner is the argument passed to transferOwnership (fuzzed address)
    function testFuzz_property(address ownerCandidate, address newOwner) public {
        // keep wide domain but avoid zero-address ambiguity for ownerCandidate when we need a valid owner
        // allow ownerCandidate == address(0) as initial owner is possible only if we explicitly set it.

        // make ownerCandidate the owner by initializing c and transferring ownership if needed
        // First, initialize contract (sets owner to msg.sender)
        vm.prank(address(this));
        c.initialize();

        // Now current owner is address(this). We want to test behavior when the caller is the owner.
        // We'll impersonate the owner and call transferOwnership, so the caller must equal current owner.
        // If fuzz provides an ownerCandidate different from address(this), we can transfer ownership first
        // from address(this) to ownerCandidate (so ownerCandidate becomes owner) and then have that
        // ownerCandidate call transferOwnership(newOwner).

        if (ownerCandidate != address(this)) {
            // transfer ownership from address(this) to ownerCandidate
            vm.prank(address(this));
            c.transferOwnership(ownerCandidate);
            // now owner() should be ownerCandidate
            // proceed with ownerCandidate calling transferOwnership(newOwner)
        }

        // Now owner() == ownerCandidate (if ownerCandidate==address(this) it stayed as address(this))
        // Have ownerCandidate call transferOwnership(newOwner)
        vm.prank(ownerCandidate);
        // perform the call and observe whether it succeeds (we don't expect revert for valid flows)
        // Use try/catch to capture revert behavior if any (allowed by rules)
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the correct contract ensures that owner() == newOwner (regardless of addresses equality)
        // Even if newOwner == address(0), reference contract enforces newOwner != address(0) and would revert,
        // but our setup ensures the caller is the owner so the behavior is deterministic: reference will revert
        // when newOwner == address(0). To keep the property universally true for the reference across all inputs,
        // we assert a single fact that covers both outcomes: if the call succeeded (ok==true) then owner() must equal newOwner.
        // The mutant makes the call succeed but sets owner() == caller, violating this assertion for some inputs.

        if (ok) {
            // exactly one assertion as required
            assertTrue(c.owner() == newOwner);
        } else {
            // If call reverted, then reference also reverts for the same input (e.g., newOwner==address(0)), so
            // we assert that owner() did not change from caller to some other unexpected value: owner() must not be newOwner
            // is NOT a universal property of reference; but to keep single assertion requirement we only assert when ok==true.
            // However test requires exactly one assertTrue in all executions; to satisfy that, we transform: when call reverted,
            // the expected property is that owner() != newOwner (since transfer didn't succeed). That holds for reference.
            // So assertTrue with conditional boolean covers both branches in single assertion expression.
            assertTrue(ok ? (c.owner() == newOwner) : (c.owner() != newOwner));
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed caller address `actor` will be used to call initialize().
    // General rule: after initialize() completes, the reference implementation sets owner() == msg.sender;
    // the mutant that omits __Context_init_unchained can leave owner() != msg.sender for some callers.
    function testFuzz_property(address actor) public {
        // keep actor non-zero to be a meaningful caller
        vm.assume(actor != address(0));

        // make the fuzzed actor call initialize()
        vm.prank(actor);
        bool ok;
        try c.initialize() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract always results in owner() == actor (so ok==true and owner==actor)
        // We assert the universal property: either initialize reverted (ok==false) OR owner() == actor.
        // For the correct contract initialize() should succeed and owner() == actor for all actor inputs.
        // The buggy mutant that omitted __Context_init_unchained may leave owner() != actor for some actor
        // so this assertion will fail for that mutant for some fuzzed actor.
        assertTrue(!ok || c.owner() == actor);
    }
}

