contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz over a caller address; for any EOA caller, reference should set owner() to caller via initializer chain.
    function testFuzz_property(address caller) public {
        // keep domain wide but exclude zero address which is often used specially
        vm.assume(caller != address(0));
        // make sure caller is an EOA by ensuring no code at address
        // fuzzer may pick an address with code; avoid that to match adversarial-free scenario
        vm.assume(caller.code.length == 0);

        // impersonate caller and call initialize
        vm.prank(caller);
        c.initialize();

        // The single assertion: owner() equals the caller for all admissible callers.
        assertTrue(c.owner() == caller);
    }
}

