pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz a contract-deployer seed so the fuzzer will find a contract caller address
    function testFuzz_property(uint256 deployerSeed) public {
        // keep domain wide
        deployerSeed = bound(deployerSeed, 1, type(uint256).max);

        // deploy a minimal caller contract (adversarial counterpart) whose caller context is a contract
        DeployerCaller caller = new DeployerCaller(address(c), deployerSeed);

        // ensure the deployed caller has code (isContract == true)
        require(AddressCheck.isContract(address(caller)), "helper must be a contract");

        // call initialize from the helper contract (it will call c.initialize())
        bool ok;
        try caller.callInitialize() {
            ok = true;
        } catch {
            ok = false;
        }

        // general rule: for any contract caller, reference implementation sets owner() == caller after initialize
        // (this assertion reads c.owner() and compares to the caller address)
        assertTrue(ok && c.owner() == address(caller));
    }
}

// Helper contract that calls initialize on C from a contract context
contract DeployerCaller {
    address public target;
    uint256 public seed;
    constructor(address _target, uint256 _seed) payable {
        target = _target;
        seed = _seed;
    }

    function callInitialize() external {
        // call initialize on target
        C(target).initialize();
    }
}

// small library to check address.code.length without importing other files
library AddressCheck {
    function isContract(address account) internal view returns (bool) {
        return account.code.length > 0;
    }
}

