pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an arbitrary nonzero Ether amount to fund the caller contract so it can make an external call
    function testFuzz_property(uint256 fund) public {
        // keep fund in a reasonable wide range but allow zero too
        fund = bound(fund, 0, 1 ether);

        // Deploy a contract that will call c.initialize() from its fallback (so the call originates from a contract)
        CallerContract caller = new CallerContract(address(c));

        // Fund the caller contract so it can call
        if (fund > 0) {
            vm.deal(address(this), fund);
            payable(address(caller)).transfer(fund);
        }

        // The reference C: when an external contract invokes initialize() (via its fallback),
        // __Context_init_unchained ensures owner() becomes the calling contract's address.
        // We perform the call from the helper contract. Capture whether initialize succeeded.
        bool ok;
        try caller.doCallInitialize() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after the helper contract calls initialize(), owner() == address(caller).
        // The reference satisfies this for all admissible inputs (fund padded), the mutant (omitting __Context_init_unchained)
        // will fail for some caller behaviors (this test lets the fuzzer find such a case).
        assertTrue(ok && c.owner() == address(caller));
    }
}

// Helper contract that, when asked, triggers c.initialize() from its fallback via a low-level call
contract CallerContract {
    address target;
    constructor(address _target) payable {
        target = _target;
    }

    // entrypoint: make a low-level call to trigger fallback-based behavior
    function doCallInitialize() external {
        // call with empty calldata so that if we encode to hit initialize via a low-level call
        // we instead call initialize() directly via an external call from this contract
        (bool success, ) = target.call(abi.encodeWithSignature("initialize()"));
        require(success, "init call failed");
    }

    // allow contract to receive funds
    receive() external payable {}
}

